"""Generate experimental role adaptations from *measured combined vocal stems*.
Not a claim of separately analysed main/harmony/crowd production. No audio is bundled.
"""
from pathlib import Path
import json,statistics,math
root=Path(__file__).resolve().parents[1]
rows=json.loads((root/'assets/references/audio_measurements.json').read_text())
profiles=[]
for artist in dict.fromkeys(r['requested_act'] for r in rows):
    refs=[r for r in rows if r['requested_act']==artist and 'vocal_estimate' in r['measurements']]
    # Do not give duplicate catalogue editions of the same title extra weight.
    unique={}
    for r in refs:unique.setdefault(r['title'].casefold(),r)
    refs=list(unique.values())
    m=[r['measurements']['vocal_estimate'] for r in refs]
    centroid=statistics.median(v['spectral_centroid_hz'] for v in m)
    crest=statistics.median(v['crest_db'] for v in m)
    presence=statistics.median(v['band_energy_fraction']['1000-4000'] for v in m)
    high=statistics.median(v['band_energy_fraction']['4000-8000'] for v in m)
    width=statistics.median(v['side_mid_db'] for v in m)
    clamp=lambda x,lo,hi:round(max(lo,min(hi,x)),5)
    reference='; '.join(r['catalog_url'] for r in refs)
    # Conservative feature-conditioned role adaptations, not inferred original chains.
    main_variant=2 if centroid>1900 else 1 if centroid<1350 else 0
    backing_variant=9 if crest>15 else 7 if centroid>1900 else 8 if centroid<1350 else 6 if width>-12 else 5
    choir_variant=13 if crest>15 else 11 if width>-8 else 12 if centroid>1900 else 10
    for role,variant in [('Main',main_variant),('Harmony/Backing',backing_variant),('Chor/Crowd',choir_variant)]:
        choir=role=='Chor/Crowd'; backing=role=='Harmony/Backing'
        amount=clamp(.28+(14-crest)*.035,.16,.52)
        values={'druck.amount':amount,'klang.amount':clamp(.17+(centroid-1500)/4500,.08,.38),'waerme.amount':clamp(.12+(1800-centroid)/6000,.04,.3),'breite.amount':clamp((width+26)/75,.04,.25) if role=='Main' else .45 if backing else .7,'raum.amount':.13 if role=='Main' else .28 if backing else .40,'bewegung.amount':0,'fet.threshold':clamp(-18-(14-crest)*.35,-21,-16),'eq2.gain':clamp((presence-.40)*7,-2,2),'eq3.gain':clamp((high-.08)*10,-1,1.5),'deess.on':1,'deess.low':5500 if centroid>1700 else 4200,'deess.high':11000,'deess.threshold':-25,'deess.amount':clamp(.4+high,.4,.65),'res.on':1,'res.amount':.25,'res.max':5,'air.on':1,'air.high':clamp(high*.5,.015,.10),'air.guard':.85,'reverb.tail':1.1 if role=='Main' else 1.5 if backing else 2.2,'reverb.fade':.4,'long.beats':.5 if role=='Main' else .75,'long.feedback':.22,'duck.amount':.65,'double.voices':4 if not choir else 7,'stadium.on':0,'tune.on':0,'creative.on':0,'fx.mix':.6,'output':-3 if role=='Main' else -4 if backing else -5,'throw.type':2,'throw.beats':.5,'throw.feel':1,'throw.feedback':.35,'throw.return':.25,'throw.verb.on':1 if choir else 0,'throw.verb.amount':.18}
        for section in ['druck','klang','waerme','breite','raum','bewegung']:values[section+'.variant']=variant
        input_note='Trockene einzelne Leadstimme.' if role=='Main' else 'Bereits eingesungene Harmonien oder echte weitere Doubles einspeisen; keine automatische Harmonieerzeugung.' if backing else 'Echte Unisono-/Gruppen-Takes bevorzugt. Der Doubler erzeugt nur synthetische Unisono-Stimmen; Stadium bleibt bis zur Samplewahl aus.'
        description=f'Experimentelle {role}-Anpassung aus Messungen einer kombinierten Demucs-Vocal-Schaetzung. Keine getrennte Rollen-Hoeranalyse, keine identische Rekonstruktion, kein offizielles Kuenstlerpreset. {input_note} Input auf vergleichbaren Pegel kalibrieren, Output abgleichen. Centroid {centroid:.0f} Hz / Crest {crest:.1f} dB sind Messwerte des Referenzausschnitts, keine urspruenglichen EQ-/Kompressorwerte.'
        profiles.append({'name':artist+' - '+role+' Studie','category':'Studie/'+role,'description':description,'reference':reference,'status':'Experimental: combined-vocal measurement; role adaptation unverified','reference_track_ids':[r['track_id'] for r in refs],'values':values})
(root/'assets/references/presets.json').write_text(json.dumps(profiles,ensure_ascii=False,indent=2)+'\n')
q=lambda s:json.dumps(s,ensure_ascii=True)
lines=['// Generated by scripts/generate_reference_presets.py; do not maintain a second bank.']
for pr in profiles:
    lines+=['{ auto v=defaults();']+[f'v[size_t(index({q(k)}))]={float(v):.7f}f;' for k,v in pr['values'].items()]
    lines += ['Preset pr{'+q(pr['name'])+','+q(pr['category'])+',v};',f'pr.description={q(pr["description"])};',f'pr.reference={q(pr["reference"])};',f'pr.status={q(pr["status"])};p.push_back(std::move(pr));}}']
(root/'Source/ReferencePresets.inc').write_text('\n'.join(lines)+'\n')
print('Generated',len(profiles),'experimental global presets')
